/**
 * The fixture day (test/fixtures/README.md), generated by the engine:
 * Runloop Commons, seed 42, 80 residents, Day 1 08:00–09:00, with two agents
 * housed through commands (one goes live), a rejected housing command and a
 * clock change to 4×.
 *
 *   pnpm --filter @runloop-world/sim fixtures          # rewrite the files
 *
 * fixtures.test.ts checks that the committed files equal this output.
 */
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import type { CommandEnvelope, WorldEvent, WorldSnapshot } from '@runloop-world/events';
import { commons, newWorld, runUntil } from '../helpers';

export const FIXTURE = { worldId: 'fixture-commons', seed: 42, population: 80, snapshotTick: 495, endTick: 540 } as const;
export const AGENT_A = 'agt_5f1c2a8e-3b4d-4c6e-9a7b-1d2e3f405a61';
export const AGENT_B = 'agt_9b2d4e6f-1a3c-4e5d-8f7a-2b3c4d5e6f70';
export const AGENT_C = 'agt_0c1d2e3f-4a5b-4c6d-9e7f-8091a2b3c4d5';
export const RUN = '7c9e6679-7425-40de-944b-e07fc1f90ae7';

function inputs(): Map<number, CommandEnvelope[]> {
  const at = new Map<number, CommandEnvelope[]>();
  const add = (tick: number, env: CommandEnvelope) => at.set(tick, [...(at.get(tick) ?? []), env]);
  const conn = (n: number, agentId: string, health: 'awaiting_first_event' | 'live', attention: 'none' | 'permission_requested' = 'none'): CommandEnvelope => ({
    id: `conn:${agentId}:${n}`,
    source: 'system',
    command: { type: 'agent.connection', agentId, health, attention },
  });
  add(481, { id: `house:${AGENT_A}`, source: 'user', command: { type: 'agent.house', agentId: AGENT_A, lotId: 'lot_agent_1', displayName: 'Engineering House', hue: '#5aa9f5' } });
  add(481, conn(1, AGENT_A, 'awaiting_first_event'));
  add(482, { id: `house:${AGENT_B}`, source: 'user', command: { type: 'agent.house', agentId: AGENT_B, lotId: 'lot_agent_4', displayName: 'Docs Desk', hue: '#e0946a' } });
  add(482, conn(1, AGENT_B, 'awaiting_first_event'));
  add(484, { id: `ses:${RUN}:started`, source: 'external-agent', cause: { runId: RUN, seqFrom: 1, seqTo: 1 }, command: { type: 'agent.session', agentId: AGENT_A, runId: RUN, phase: 'started' } });
  add(484, conn(2, AGENT_A, 'live'));
  add(486, {
    id: `act:${RUN}:14`,
    source: 'external-agent',
    cause: { runId: RUN, seqFrom: 1, seqTo: 14 },
    command: { type: 'agent.activity', agentId: AGENT_A, runId: RUN, counts: { read: 4, search: 2, edit: 1 }, execState: 'working', helpers: 1, openIncidents: 0 },
  });
  add(487, { id: `house:${AGENT_C}`, source: 'user', command: { type: 'agent.house', agentId: AGENT_C, lotId: 'lot_agent_1', displayName: 'Third Agent', hue: '#7fa8c9' } });
  add(488, { id: 'clock:1', source: 'user', command: { type: 'clock.set', speed: 4 } });
  add(531, {
    id: `act:${RUN}:22`,
    source: 'external-agent',
    cause: { runId: RUN, seqFrom: 1, seqTo: 22 },
    command: { type: 'agent.activity', agentId: AGENT_A, runId: RUN, counts: { read: 6, search: 2, edit: 3, test: 1 }, execState: 'awaiting_approval', helpers: 1, openIncidents: 0 },
  });
  add(531, conn(3, AGENT_A, 'live', 'permission_requested'));
  return at;
}

/** The fixture day: every event, and the snapshot at the end of `snapshotTick`. */
export function generateFixtures(): { events: WorldEvent[]; snapshot: WorldSnapshot } {
  const run = newWorld({ worldId: FIXTURE.worldId, seed: FIXTURE.seed, population: FIXTURE.population, strict: true, town: commons() });
  let snapshot: WorldSnapshot | null = null;
  runUntil(run, FIXTURE.endTick, {
    inputs: inputs(),
    each: (t) => {
      if (t === FIXTURE.snapshotTick) snapshot = structuredClone(run.state);
    },
  });
  return { events: run.events, snapshot: snapshot! };
}

/** One event per line; the snapshot with one resident per line. */
export function formatEvents(events: readonly WorldEvent[]): string {
  return `[\n${events.map((e) => `  ${JSON.stringify(e)}`).join(',\n')}\n]\n`;
}

export function formatSnapshot(s: WorldSnapshot): string {
  const { residents, buildings, agents, affinity, ...head } = s;
  const lines = Object.entries(head).map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)}`);
  const list = (k: string, xs: readonly unknown[]) => `  ${JSON.stringify(k)}: [\n${xs.map((x) => `    ${JSON.stringify(x)}`).join(',\n')}\n  ]`;
  return `{\n${[...lines, list('residents', residents), list('buildings', buildings), list('agents', agents), `  "affinity": ${JSON.stringify(affinity)}`].join(',\n')}\n}\n`;
}

if (process.argv.includes('--write')) {
  const dir = import.meta.dirname;
  const { events, snapshot } = generateFixtures();
  writeFileSync(path.join(dir, 'commons-day1.events.json'), formatEvents(events));
  writeFileSync(path.join(dir, 'commons-day1.snapshot.json'), formatSnapshot(snapshot));
  const walking = snapshot.residents.filter((r) => r.motion).length;
  const outdoor = snapshot.residents.filter((r) => r.place.kind === 'outdoor').length;
  console.log(`${events.length} events; snapshot at seq ${snapshot.seq} (tick ${snapshot.tick}): ${walking} walking, ${outdoor} outdoors`);
}
